import { pluginInstanceInvocation } from "../plugins/plugin-instance-invocation.js";
import { PluginInvocationScope } from "../plugins/plugin-invocation-scope.js";
import type { PluginRegistry } from "../plugins/registry-types.js";

const withQueue = useIngressMonitorQueueFixture();

const NOT_INITIALIZED = "Telegram runtime not initialized";

/** Same construction as extensions/telegram/src/runtime.ts. */
function createTelegramLikeRuntimeStore(id: string) {
