    pluginId: `telegram-repro-${id}`,
    errorMessage: NOT_INITIALIZED,
  });
}

/**
 * Same shape as createPreparedModelRuntimeLease (prepared-model-runtime.plugin-lifetime.ts) when
 * a loaded plugin opts into generationOverlap (memory-core and llm-task do): a retained scope with
 * at least one consumer.
 */
function createReplyRunLeaseScope() {
  const overlapInstance = {
    retainConsumer: () => ({ release() {}, close: async () => {} }),
  };
  return new PluginInvocationScope({} as PluginRegistry, [overlapInstance as never], {
    retained: true,
  });
}

type Scenario = {
  abandonFrom: "reply-run-lease" | "plugin-instance";
  /** Fix direction: run every pump in the context captured when the monitor was created. */
  pumpInOwnerContext?: boolean;
};

async function replayAbandonedUpdate(scenario: Scenario) {
  return await withQueue(async (queue) => {
    const id = `${scenario.abandonFrom}-${scenario.pumpInOwnerContext ? "owner" : "inherit"}`;
    const store = createTelegramLikeRuntimeStore(id);
    const telegramInstance = { pluginId: "telegram", slots: new Map() };
    const leaseScope = createReplyRunLeaseScope();
    const attempts: string[] = [];
    const retryTimers: string[] = [];
    let completed = false;
    const originalSetTimeout = globalThis.setTimeout;
    const timers = vi.spyOn(globalThis, "setTimeout").mockImplementation(((
      callback: () => void,
      ms?: number,
      ...rest: unknown[]
    ) => {
      if ((new Error("probe").stack ?? "").includes("onRetryAt")) {
        retryTimers.push(pluginInstanceInvocation.getStore()?.instance ? "telegram" : "none");
      }
      return originalSetTimeout(callback, ms, ...rest);
    }) as never);
    try {
      await pluginInstanceInvocation.run(
        { instance: telegramInstance as never, token: {} },
        async () => {
          // Registration: setTelegramRuntime(api.runtime) inside the plugin instance.
          store.setRuntime({ name: "telegram" });
          const runInOwner = AsyncLocalStorage.snapshot();
          const monitor = createMonitor(
            queue,
            async (_raw, lifecycle) => {
              // The Telegram inbound handler reads its runtime first (enforceTelegramDmAccess ->
              // createTelegramIngressResolver -> getTelegramRuntime in the instrumented dry run).
              const runtime = store.tryGetRuntime();
              attempts.push(runtime ? "runtime" : NOT_INITIALIZED);
              if (!runtime) {
                return { kind: "failed-retryable", error: new Error(NOT_INITIALIZED) };
              }
              if (attempts.length === 1) {
                // Telegram text DMs are buffered by the inbound debouncer (default 300 ms,
                // bot-handlers.inbound-buffer.ts). The handler creates a spooled-replay
                // participant and telegram-ingress-drain.ts returns { kind: "deferred" } at
