                const abandon = () => {
                  void lifecycle.onAbandoned();
                };
                setTimeout(() => {
                  if (scenario.abandonFrom === "reply-run-lease") {
                    leaseScope.run(abandon);
                  } else {
                    abandon();
                  }
                }, 50);
                return { kind: "deferred" };
              }
              await lifecycle.onAdopted();
              completed = true;
              return { kind: "completed" };
            },
            {
              // Telegram's drain uses deferredLaneOccupancy "release" (telegram-ingress-drain.ts).
              retryPolicy: { baseMs: 20, maxMs: 20 },
              deferredLaneOccupancy: "release",
              ...(scenario.pumpInOwnerContext
                ? { runPumpTask: (work: () => Promise<void>) => runInOwner(work) }
                : {}),
            },
          );
